#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_append_n_resize_failure(void) {
    // Setup: create a buffer with small size and some initial data
    // We want self->len <= needed so that resize is triggered
    // helper_make_buffer_with_data is not in the operation map, so use buffer_new_with_copy
    const char *initial = "abc";
    buffer_t *buf = buffer_new_with_copy(initial);
    TEST_ASSERT_NOT_NULL(buf);

    // The buffer's size is strlen(initial) = 3
    // Let's append 2 more bytes, so needed = 3 (prev) + 2 = 5 > self->len (which is 3)
    const char *to_append = "XY";
    size_t append_len = 2;

    // We want buffer_resize to fail. 
    // buffer_new_with_copy does 2 allocations (buffer_new_with_size: malloc + calloc)
    // buffer_append_n will call buffer_resize, which calls realloc (the 3rd allocation)
    malloc_fail_after(2); // fail the 3rd allocation (the realloc in buffer_resize)

    int ret = buffer_append_n(buf, to_append, append_len);

    // Should return -1 due to resize failure
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer's data should remain unchanged
    helper_assert_buffer_data_equals(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_failure);
    return UNITY_END();
}

